import{_ as s,o as n,c as e,a5 as i}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"80. Practice: Fix Memory and Logic Bugs","description":"The Little Book of C — 80. Practice: Fix Memory and Logic Bugs","frontmatter":{"title":"80. Practice: Fix Memory and Logic Bugs","date":"2026-07-04","categories":"[C 教程]","tags":"[C, Little Book of C, Debugging Testing Profiling]","description":"The Little Book of C — 80. Practice: Fix Memory and Logic Bugs","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":"80","sidebarWeight":"80","lang":"en-US","alternateEn":"/posts/c教程/en-US/08-Debugging Testing Profiling/080-Practice Fix Memory and Logic Bugs","alternateZh":"/posts/c教程/zh-CN/08-调试测试与 profiling/080-Practice Fix Memory and Logic Bugs"},"headers":[],"relativePath":"posts/c教程/en-US/08-Debugging Testing Profiling/080-Practice Fix Memory and Logic Bugs.md","filePath":"posts/c教程/en-US/08-Debugging Testing Profiling/080-Practice Fix Memory and Logic Bugs.md","lastUpdated":1790163617000}'),t={name:"posts/c教程/en-US/08-Debugging Testing Profiling/080-Practice Fix Memory and Logic Bugs.md"};function p(l,a,o,c,r,d){return n(),e("div",null,[...a[0]||(a[0]=[i(`<p>[中文版本](/posts/c教程/zh-CN/08-调试测试与 profiling/080-Practice Fix Memory and Logic Bugs)</p><h4 id="follow-along-deliverable" tabindex="-1">Follow-Along Deliverable <a class="header-anchor" href="#follow-along-deliverable" aria-label="Permalink to &quot;Follow-Along Deliverable&quot;">​</a></h4><ul><li>Assumed state: lessons 071-079 are complete and you can rebuild the previous example.</li><li>Working directory: <code>~/c-course-labs/080-debug-lab</code>.</li><li>First command: on macOS / Linux run <code>mkdir -p ~/c-course-labs/080-debug-lab &amp;&amp; cd ~/c-course-labs/080-debug-lab</code>; on Windows PowerShell run <code>New-Item -ItemType Directory -Force &quot;$HOME\\c-course-labs\\080-debug-lab&quot;; Set-Location &quot;$HOME\\c-course-labs\\080-debug-lab&quot;</code>.</li><li>Success evidence: keep the source file, executable, <code>evidence.md</code>, and record before-fix failure, diagnosis method, after-fix output, and memory-check or assertion result.</li><li>Boundary for this lab: This lab is about repair evidence, not feature count. A full test framework or CI pipeline is out of scope.</li><li>Reset: remove the executable, temporary data, and generated output for this lab; keep source and <code>evidence.md</code> for review.</li></ul><p>Now it’s time to apply everything you’ve learned, debugging, testing, assertions, logging, and analysis, to real code that’s broken. This section walks you through a handful of small, common C bugs that new programmers (and even experienced ones) run into, showing how to find, understand, and fix them.</p><h4 id="step-1-bug-1-segmentation-fault-from-a-bad-pointer" tabindex="-1">Step 1. Bug #1, Segmentation Fault from a Bad Pointer <a class="header-anchor" href="#step-1-bug-1-segmentation-fault-from-a-bad-pointer" aria-label="Permalink to &quot;Step 1. Bug #1, Segmentation Fault from a Bad Pointer&quot;">​</a></h4><p>Buggy Code:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int *p;</span></span>
<span class="line"><span>    *p = 10;</span><span>  // writing to uninitialized pointer</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, *p);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Symptom:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Segmentation fault (core dumped)</span></span></code></pre></div><p>Diagnosis:</p><ul><li>The pointer<code>p</code> is never initialized.</li><li>It points to an undefined address.</li></ul><p>Fix:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int x = 10;</span></span>
<span class="line"><span>    int *p = &amp;x;</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, *p);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Lesson: Always initialize pointers before use. If dynamic, allocate with<code>malloc()</code> and check for<code>NULL</code>.</p><h4 id="step-2-bug-2-memory-leak" tabindex="-1">Step 2. Bug #2, Memory Leak <a class="header-anchor" href="#step-2-bug-2-memory-leak" aria-label="Permalink to &quot;Step 2. Bug #2, Memory Leak&quot;">​</a></h4><p>Buggy Code:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>void leak(void) {</span></span>
<span class="line"><span>    int *arr = malloc(10 * sizeof(int));</span></span>
<span class="line"><span>    for (int i = 0; i &lt; 10; i++) arr[i] = i;</span></span>
<span class="line"><span>    // forgot to free</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    for (int i = 0; i &lt; 10000; i++) leak();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Diagnosis: Each call to<code>leak()</code> allocates memory and never frees it. Use Valgrind to confirm:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>valgrind ./a.out</span></span></code></pre></div><p>Fix:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void leak(void) {</span></span>
<span class="line"><span>    int *arr = malloc(10 * sizeof(int));</span></span>
<span class="line"><span>    if (!arr) return;</span></span>
<span class="line"><span>    for (int i = 0; i &lt; 10; i++) arr[i] = i;</span></span>
<span class="line"><span>    free(arr);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Lesson: Every<code>malloc()</code> needs a matching<code>free()</code>, no exceptions.</p><h4 id="step-3-bug-3-off-by-one-error" tabindex="-1">Step 3. Bug #3, Off-by-One Error <a class="header-anchor" href="#step-3-bug-3-off-by-one-error" aria-label="Permalink to &quot;Step 3. Bug #3, Off-by-One Error&quot;">​</a></h4><p>Buggy Code:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int nums[5] = {0, 1, 2, 3, 4};</span></span>
<span class="line"><span>    for (int i = 0; i &lt;= 5; i++)  // ❌ should be &lt; 5</span></span>
<span class="line"><span>        printf(&quot;%d &quot;, nums[i]);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Symptom: Sometimes prints garbage or segfaults.</p><p>Fix:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>for (int i = 0; i &lt; 5; i++)</span></span></code></pre></div><p>Lesson: Off-by-one errors are the most common bug in loops. Always check your boundary conditions carefully.</p><h4 id="step-4-bug-4-use-after-free" tabindex="-1">Step 4. Bug #4, Use-After-Free <a class="header-anchor" href="#step-4-bug-4-use-after-free" aria-label="Permalink to &quot;Step 4. Bug #4, Use-After-Free&quot;">​</a></h4><p>Buggy Code:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int *x = malloc(sizeof(int));</span></span>
<span class="line"><span>    *x = 5;</span></span>
<span class="line"><span>    free(x);</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, *x);  // ❌ accessing freed memory</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Fix:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>free(x);</span></span>
<span class="line"><span>x = NULL;</span></span></code></pre></div><p>Now:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (x) printf(&quot;%d\\n&quot;, *x);</span></span></code></pre></div><p>Lesson: Once you free memory, it’s no longer yours, never touch it again.</p><h4 id="step-5-bug-5-stack-variable-escaping-scope" tabindex="-1">Step 5. Bug #5, Stack Variable Escaping Scope <a class="header-anchor" href="#step-5-bug-5-stack-variable-escaping-scope" aria-label="Permalink to &quot;Step 5. Bug #5, Stack Variable Escaping Scope&quot;">​</a></h4><p>Buggy Code:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int *make_ptr(void) {</span></span>
<span class="line"><span>    int x = 10;</span></span>
<span class="line"><span>    return &amp;x;  // ❌ pointer to local variable</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int *p = make_ptr();</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, *p);  // UB</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Fix:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int *make_ptr(void) {</span></span>
<span class="line"><span>    int *x = malloc(sizeof(int));</span></span>
<span class="line"><span>    *x = 10;</span></span>
<span class="line"><span>    return x;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>and remember to<code>free(p)</code> later.</p><p>Lesson: Never return the address of a local variable, its lifetime ends when the function returns.</p><h4 id="step-6-bug-6-missing-return-statement" tabindex="-1">Step 6. Bug #6, Missing Return Statement <a class="header-anchor" href="#step-6-bug-6-missing-return-statement" aria-label="Permalink to &quot;Step 6. Bug #6, Missing Return Statement&quot;">​</a></h4><p>Buggy Code:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int add(int a, int b) {</span></span>
<span class="line"><span>    int c = a + b;</span></span>
<span class="line"><span>    // forgot to return</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, add(2, 3));</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Fix:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>return c;</span></span></code></pre></div><p>Lesson: If the function’s return type is non-<code>void</code>, always return a value. Compile with<code>-Wall -Wextra</code> to catch this automatically.</p><h4 id="step-7-bug-7-uninitialized-variable" tabindex="-1">Step 7. Bug #7, Uninitialized Variable <a class="header-anchor" href="#step-7-bug-7-uninitialized-variable" aria-label="Permalink to &quot;Step 7. Bug #7, Uninitialized Variable&quot;">​</a></h4><p>Buggy Code:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int sum(void) {</span></span>
<span class="line"><span>    int s;</span></span>
<span class="line"><span>    for (int i = 0; i &lt; 3; i++) s += i;  // s not initialized</span></span>
<span class="line"><span>    return s;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Fix:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int s = 0;</span></span></code></pre></div><p>Lesson: Initialize all variables before using them, especially accumulators.</p><h4 id="step-8-bug-8-mixing-signed-and-unsigned" tabindex="-1">Step 8. Bug #8, Mixing Signed and Unsigned <a class="header-anchor" href="#step-8-bug-8-mixing-signed-and-unsigned" aria-label="Permalink to &quot;Step 8. Bug #8, Mixing Signed and Unsigned&quot;">​</a></h4><p>Buggy Code:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int a = -1;</span></span>
<span class="line"><span>    unsigned int b = 1;</span></span>
<span class="line"><span>    if (a &lt; b) printf(&quot;less\\n&quot;); else printf(&quot;greater\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>greater</span></span></code></pre></div><p>Explanation:<code>a</code> is converted to unsigned, so it becomes a large positive number.</p><p>Fix: Avoid mixing signed and unsigned types. Use explicit casts or consistent types.</p><h4 id="step-9-bug-9-buffer-overflow" tabindex="-1">Step 9. Bug #9, Buffer Overflow <a class="header-anchor" href="#step-9-bug-9-buffer-overflow" aria-label="Permalink to &quot;Step 9. Bug #9, Buffer Overflow&quot;">​</a></h4><p>Buggy Code:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;string.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    char name[8];</span></span>
<span class="line"><span>    strcpy(name, &quot;Superlongname&quot;);  // ❌ too big</span></span>
<span class="line"><span>    printf(&quot;%s\\n&quot;, name);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Fix:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>strncpy(name, &quot;Superlongname&quot;, sizeof(name) - 1);</span></span>
<span class="line"><span>name[7] = &#39;\\0&#39;;</span></span></code></pre></div><p>Lesson: Never trust input size, always use bounded functions.</p><h4 id="step-10-bug-10-floating-point-comparison" tabindex="-1">Step 10. Bug #10, Floating-Point Comparison <a class="header-anchor" href="#step-10-bug-10-floating-point-comparison" aria-label="Permalink to &quot;Step 10. Bug #10, Floating-Point Comparison&quot;">​</a></h4><p>Buggy Code:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    float a = 0.1f * 3;</span></span>
<span class="line"><span>    if (a == 0.3f) printf(&quot;Equal\\n&quot;);</span></span>
<span class="line"><span>    else printf(&quot;Not equal\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Not equal</span></span></code></pre></div><p>Fix:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (fabsf(a - 0.3f) &lt; 1e-6) printf(&quot;Equal\\n&quot;);</span></span></code></pre></div><p>Lesson: Floating-point math is approximate, always compare with a tolerance.</p><h4 id="putting-it-all-together" tabindex="-1">Putting It All Together <a class="header-anchor" href="#putting-it-all-together" aria-label="Permalink to &quot;Putting It All Together&quot;">​</a></h4><p>You can combine all these techniques:</p><ul><li>Use assertions to catch impossible states.</li><li>Use logging to trace events.</li><li>Run Valgrind or ASan to detect memory bugs.</li><li>Use unit tests to verify correctness.</li><li>And if it still crashes, analyze the core dump.</li></ul><p>Every debugging tool is a lens. Use them together to see clearly.</p><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Debugging teaches you how programs fail. Each bug fixed makes you a more confident systems engineer. C doesn’t forgive mistakes, but it rewards precision.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Write a program containing at least 3 of these bugs.</li><li>Run it under AddressSanitizer (<code>-fsanitize=address</code>).</li><li>Fix each bug one by one.</li><li>Document what caused it and what fixed it.</li><li>Make this a personal debugging kata, practice until no bug survives longer than 10 minutes.</li></ol><p>Next, we’ll begin Chapter 9: Portable and Modern C, where you’ll learn how to write C that runs everywhere, from embedded chips to modern servers.</p>`,86)])])}const h=s(t,[["render",p]]);export{g as __pageData,h as default};
